//! Checks the port against rows recorded from the verbatim Wine C code
//! (`target/canon/mscms/*_harness.c`, built with ASan and UBSan, no reports).
//! Each row is `(commands, replies)`: the `|`-separated commands run in order, each on its own
//! input, and the `|`-separated replies must match exactly.

use crate::icc::{
    ProfileHeader, TagEntry, TagError, PROFILE_HEADER_SIZE, RESERVED_OFFSET, TAG_ENTRY_SIZE,
};
use crate::profile::{
    basename, color_directory, match_profile, standard_profile, EnumRecord, ENUMTYPEW_SIZE,
};
use crate::transform::*;
use crate::{McsError, Profile};

