/// `intents[0]` of the harness array `{2, 1, 0, 3}`, which lcms receives for every multi-profile call.
const FIRST_INTENT: u32 = 2;

#[test]
fn oracle_rows_match_wine() {
    for (commands, expected) in ROWS {
        assert_eq!(replay(commands), *expected, "commands: {commands}");
    }
}

#[test]
fn unknown_command_is_bad() {
    assert_eq!(run_command("bogus"), "bad-op");
}

fn replay(commands: &str) -> String {
    commands
        .split('|')
        .map(run_command)
        .collect::<Vec<_>>()
        .join("|")
}

fn run_command(command: &str) -> String {
    let words: Vec<&str> = command.split(' ').collect();
    match words[0] {
        "sizes" => format!(
            "hdr={PROFILE_HEADER_SIZE} reserved={RESERVED_OFFSET} tag={TAG_ENTRY_SIZE} enumw={ENUMTYPEW_SIZE}"
        ),
        "hdr" => hex(&image(words[1]).header().to_native()),
        "sethdr" => {
            let mut profile = image(words[1]);
            profile.set_header(&ProfileHeader::from_native(&native_header(words[2])));
            hex(profile.as_bytes())
        }
        "count" => image(words[1]).tag_count().to_string(),
        "entry" => tag_reply(image(words[1]).tag_entry(num(words[2]))),
        "adjusted" => tag_reply(image(words[1]).adjusted_tag(hex_u32(words[2]))),
        "get" => get_reply(&words),
        "set" => set_reply(&words),
        "consts" => consts_text(),
        "bm" => format!("type={:#x}", from_bmformat(num(words[1]))),
        "clr" => format!("type={:#x}", from_type(num(words[1]))),
        "create" => format!(
            "ok intent={} flags={}",
            rendering_intent(num(words[1])),
            flags_text(proofing_flags(words[2] != "0"))
        ),
        "multi" => match check_multi_profile(
            words[1] != "0",
            words[2] != "0",
            num(words[3]),
            num(words[4]),
        ) {
            Ok(()) => format!("ok intent={FIRST_INTENT}"),
            Err(err) => format!("fail err={}", err.win32_code().unwrap_or(0)),
        },
        "basename" => format!("name={}", ascii(basename(&wide(words[1])))),
        "dir" => dir_reply(words[1]),
        "std" => std_reply(&words),
        "match" => format!("match={}", u8::from(match_reply(&words))),
        _ => "bad-op".to_string(),
    }
}

fn get_reply(words: &[&str]) -> String {
    let profile = image(words[1]);
    let cap = optional_u32(words[3]);
    match profile.tag_data(hex_u32(words[2]), num(words[4]), cap) {
        Ok(read) => format!(
            "ok len={} linked={} data={}",
            read.data.len(),
            u8::from(read.linked),
            hex(read.data)
        ),
        Err(TagError::TooSmall { needed }) => format!("fail len={needed}"),
        Err(_) => format!("fail len={}", cap.unwrap_or(0)),
    }
}

fn set_reply(words: &[&str]) -> String {
    let mut profile = image(words[1]);
    let data = unhex(words[4]);
    match profile.set_tag_data(hex_u32(words[2]), num(words[3]), &data) {
        Ok(len) => format!("ok len={len} img={}", hex(profile.as_bytes())),
        Err(_) => format!("fail len={}", data.len()),
    }
}

fn dir_reply(text: &str) -> String {
    match color_directory(&system_dir(), optional_u32(text)) {
        Ok(dir) => format!("ok size={} dir={}", dir.len() * 2, ascii(&dir)),
        Err(size) => format!("fail size={size}"),
    }
}

fn std_reply(words: &[&str]) -> String {
    let size = optional_u32(words[3]);
    match standard_profile(
        words[1] != "0",
        hex_u32(words[2]),
        &system_dir(),
        size,
        words[4] != "0",
    ) {
        Ok(path) => format!("ok name={}", ascii(&path)),
        Err(err) => {
            let shown = match (err, size) {
                (McsError::MoreData(needed), _) => needed.to_string(),
                (_, Some(size)) => size.to_string(),
                (_, None) => "-".to_string(),
            };
            format!("fail err={} size={shown}", err.win32_code().unwrap_or(0))
        }
    }
}

fn match_reply(words: &[&str]) -> bool {
    let v: Vec<u32> = words[2].split(',').map(num).collect();
    let rec = EnumRecord {
        size: v[0],
        version: v[1],
        fields: v[2],
        cmm_type: v[3],
        class: v[4],
        data_color_space: v[5],
        connection_space: v[6],
        signature: v[7],
        platform: v[8],
        profile_flags: v[9],
        manufacturer: v[10],
        model: v[11],
        attributes: [v[12], v[13]],
        rendering_intent: v[14],
        creator: v[15],
    };
    match_profile(&rec, &ProfileHeader::from_native(&native_header(words[1])))
}

fn consts_text() -> String {
    format!(
        "BM_RGBTRIPLETS={BM_RGBTRIPLETS} BM_BGRTRIPLETS={BM_BGRTRIPLETS} BM_xRGBQUADS={BM_XRGBQUADS} \
         BM_xBGRQUADS={BM_XBGRQUADS} BM_GRAY={BM_GRAY} BM_KYMCQUADS={BM_KYMCQUADS} \
         COLOR_GRAY={COLOR_GRAY} COLOR_RGB={COLOR_RGB} COLOR_XYZ={COLOR_XYZ} COLOR_Yxy={COLOR_YXY} \
         COLOR_Lab={COLOR_LAB} COLOR_CMYK={COLOR_CMYK} INTENT_PERCEPTUAL={INTENT_PERCEPTUAL} \
         INTENT_ABSOLUTE_COLORIMETRIC={INTENT_ABSOLUTE_COLORIMETRIC} SOFTPROOFING={CMS_FLAGS_SOFTPROOFING:#x} \
         TYPE_GRAY_8={TYPE_GRAY_8:#x} TYPE_RGB_8={TYPE_RGB_8:#x} TYPE_BGR_8={TYPE_BGR_8:#x} \
         TYPE_BGRA_8={TYPE_BGRA_8:#x} TYPE_RGBA_8={TYPE_RGBA_8:#x} TYPE_CMYK_8={TYPE_CMYK_8:#x} \
         TYPE_GRAY_16={TYPE_GRAY_16:#x} TYPE_RGB_16={TYPE_RGB_16:#x} TYPE_XYZ_16={TYPE_XYZ_16:#x} \
         TYPE_Yxy_16={TYPE_YXY_16:#x} TYPE_Lab_16={TYPE_LAB_16:#x} TYPE_CMYK_16={TYPE_CMYK_16:#x}"
    )
}

fn flags_text(flags: u32) -> String {
    if flags == 0 {
        "0".to_string()
    } else {
        format!("{flags:#x}")
    }
}

fn tag_reply(tag: Option<TagEntry>) -> String {
    match tag {
        Some(tag) => format!(
            "ok sig={:08x} off={} size={}",
            tag.sig, tag.offset, tag.size
        ),
        None => "none".to_string(),
    }
}

fn image(text: &str) -> Profile {
    Profile::new(unhex(text)).expect("image of at least 132 bytes")
}

fn native_header(text: &str) -> [u8; PROFILE_HEADER_SIZE] {
    unhex(text).try_into().expect("128-byte native header")
}

fn unhex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex byte"))
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn optional_u32(text: &str) -> Option<u32> {
    text.parse().ok()
}

fn num(text: &str) -> u32 {
    text.parse().expect("decimal number")
}

fn hex_u32(text: &str) -> u32 {
    u32::from_str_radix(text, 16).expect("hex number")
}

fn ascii(units: &[u16]) -> String {
    units.iter().map(|&unit| char::from(unit as u8)).collect()
}

fn wide(text: &str) -> Vec<u16> {
    text.encode_utf16().collect()
}

fn system_dir() -> Vec<u16> {
    wide(r"C:\Windows\system32")
}
